/**
 * @name JMESPath Injection Taint Tracking
 * @description Tracks if user-provided input flows into JMESPath search queries.
 * @kind path-problem
 * @problem.severity error
 * @id py/jmespath-injection-taint
 * @tags security
 *       external/cwe/cwe-943
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module JmesPathInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider parameters of public methods as sources
    exists(Function f |
      f.getName().matches("%") and // match all for now, maybe filter later
      not f.getName().matches("_%") and // exclude private methods
      source instanceof DataFlow::ParameterNode and
      source.getScope() = f
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("jmespath").getMember(["search", "compile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module JmesPathInjectionFlow = TaintTracking::Global<JmesPathInjectionConfig>;
import JmesPathInjectionFlow::PathGraph

from JmesPathInjectionFlow::PathNode source, JmesPathInjectionFlow::PathNode sink
where JmesPathInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "JMESPath query derived from $@.", source.getNode(), "user input"

/**
 * @name JMESPath Injection Taint Tracking
 * @description Detects if function parameters flow into JMESPath queries.
 * @kind path-problem
 * @problem.severity error
 * @id py/jmespath-injection-taint
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module JmesPathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("jmespath").getMember(["search", "compile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module JmesPathFlow = TaintTracking::Global<JmesPathConfig>;
import JmesPathFlow::PathGraph

from JmesPathFlow::PathNode source, JmesPathFlow::PathNode sink
where JmesPathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "JMESPath expression depends on $@.", source.getNode(), "parameter"
